// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" ব্যবহার;
"src/models/product.hudhud" ব্যবহার;
"src/models/order.hudhud" ব্যবহার;

// Servisleri içe aktar
"src/services/auth.hudhud" ব্যবহার;
"src/services/payment.hudhud" ব্যবহার;
"src/services/notification.hudhud" ব্যবহার;

// Yardımcı শ্রেণীları içe aktar
"src/utils/validation.hudhud" ব্যবহার;
"src/utils/formatting.hudhud" ব্যবহার;

মুদ্রণ("============================================================");
মুদ্রণ("E-Ticaret Sistemi - Modüler Mimari Demo");
মুদ্রণ("============================================================\n");

// Servis örnekleri oluştur
চলক authService = নতুন AuthService();
চলক paymentService = নতুন PaymentService();
চলক notificationService = নতুন NotificationService();

মুদ্রণ("1️⃣  KULLANICI KAYDI");
মুদ্রণ("─────────────────────────────────────────────────────────\n");

// Yeni ব্যবহারıcı oluştur
চলক newUser = নতুন User("Davut Süleyman", "davut@example.com", "güvenli123");
মুদ্রণ("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email সত্যla
যদি (Validation.email(newUser.email)) {
    মুদ্রণ("✓ Email geçerli: " + newUser.email);
} নাহলে {
    মুদ্রণ("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
চলক authResult = authService.register(newUser);
যদি (authResult.success) {
    মুদ্রণ("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

মুদ্রণ("\n2️⃣  ÜRÜN OLUŞTURMA");
মুদ্রণ("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
চলক product = নতুন Product("MacBook Pro M3", 45000, 10, "Elektronik");
মুদ্রণ("Ürün oluşturuldu: " + product.bilgi());

// Fiyat সত্যla
যদি (Validation.price(product.price)) {
    মুদ্রণ("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
যদি (product.inStock()) {
    মুদ্রণ("✓ Ürün stokta mevcut");
} নাহলে {
    মুদ্রণ("✗ Ürün stokta yok");
}

মুদ্রণ("\n3️⃣  SİPARİŞ OLUŞTURMA");
মুদ্রণ("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
চলক order = নতুন Order(
    newUser.id,
    product.id,
    1,
    product.price
);
মুদ্রণ("Sipariş oluşturuldu: " + order.bilgi());

মুদ্রণ("\n4️⃣  ÖDEME İŞLEMİ");
মুদ্রণ("─────────────────────────────────────────────────────────\n");

// Ödeme işle
চলক paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

যদি (paymentResult.success) {
    মুদ্রণ("✓ " + paymentResult.message);
    মুদ্রণ("  İşlem No: " + paymentResult.transactionId);
    মুদ্রণ("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    মুদ্রণ("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    মুদ্রণ("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} নাহলে {
    মুদ্রণ("✗ Ödeme başarısız: " + paymentResult.error);
}

মুদ্রণ("\n============================================================");
মুদ্রণ("✓ E-Ticaret sistemi demo tamamlandı!");
মুদ্রণ("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
মুদ্রণ("============================================================");

