// Order Model - Sipariş Modeli

শ্রেণী Order {
    নির্মাতা(userId, productId, quantity, totalPrice) {
        নিজ.id = Math.floor(Math.random() * 10000);
        নিজ.userId = userId;
        নিজ.productId = productId;
        নিজ.quantity = quantity;
        নিজ.totalPrice = totalPrice;
        নিজ.status = "pending";
        নিজ.createdAt = "2024-03-07";
    }

    ফাংশন bilgi() {
        ফেরত "Sipariş #" + নিজ.id + " - Kullanıcı: " + নিজ.userId + ", Ürün: " + নিজ.productId + ", Adet: " + নিজ.quantity + ", Toplam: " + নিজ.totalPrice + " TL, Durum: " + নিজ.status;
    }

    ফাংশন confirm() {
        নিজ.status = "confirmed";
    }

    ফাংশন getId() {
        ফেরত নিজ.id;
    }
}

