files.src/utils/formatting.hudhud:
// Formatting Utilities - Formatlama Fonksiyonları

শ্রেণী Formatting {
    স্থির ফাংশন currency(amount, currency) {
        যদি (currency == "TRY") {
            ফেরত amount + " ₺";
        } নাহলে {
            যদি (currency == "USD") {
                ফেরত "$" + amount;
            } নাহলে {
                যদি (currency == "EUR") {
                    ফেরত "€" + amount;
                } নাহলে {
                    ফেরত amount + " " + currency;
                }
            }
        }
    }

    স্থির ফাংশন date(date) {
        ফেরত date;
    }

    স্থির ফাংশন phone(phone) {
        // (555) 123-4567 formatı
        ফেরত "(" + phone + ")";
    }

    স্থির ফাংশন number(num) {
        // 1,234,567 formatı
        ফেরত num;
    }
}

files.src/utils/validation.hudhud:
// Validation Utilities - Doğrulama Fonksiyonları

শ্রেণী Validation {
    স্থির ফাংশন email(email) {
        // Basit email সত্যlama
        ফেরত email.length > 5;
    }

    স্থির ফাংশন password(password) {
        // Şifre en az 6 karakter olmalı
        ফেরত password.length >= 6;
    }

    স্থির ফাংশন price(price) {
        ফেরত price > 0;
    }

    স্থির ফাংশন phone(phone) {
        // Telefon numarası সত্যlama
        ফেরত phone.length == 10;
    }

    স্থির ফাংশন required(value) {
        ফেরত value.length > 0;
    }
}

