    স্থির ফাংশন currency(amount, currency) {
        যদি (currency == "TRY") {
            ফেরত amount + " ₺";
        } নাহলে {
            যদি (currency == "USD") {
                ফেরত "$" + amount;
            } নাহলে {
                যদি (currency == "EUR") {
                    ফেরত "€" + amount;
                } নাহলে {
                    ফেরত amount + " " + currency;
                }
            }
        }
    }

    স্থির ফাংশন date(date) {
        ফেরত date;
    }

    স্থির ফাংশন phone(phone) {
